#define main legacy_main
#include "native_instrument.cpp"
#undef main
static void settle(re::Core&c){float l[128]{},r[128]{};for(int i=0;i<4;i++){c.render(l,r,128);std::this_thread::sleep_for(std::chrono::milliseconds(10));}}
static int control(re::Core&c,int parameter){c.set(4,0);c.set(5,0);settle(c);auto label=text(c,5);auto n=std::stoi(label.substr(label.find('/')+1));for(int page=0;page<n;page++){c.set(5,page/511.f);settle(c);auto e=extra(c);for(int k=8;k<24;k++){uint64_t b=e["bindings"][k];if(b&&int(b&65535)-4==parameter)return k<16?k+6:k+73;}}throw std::runtime_error("Missing source control "+std::to_string(parameter));}
static void write(re::Core&c,int p,float v){int k=control(c,p);c.set(k,v);settle(c);}
static re::Json native(re::Core&c){auto e=extra(c);auto bytes=e["graph"]["cells"][0]["native_state"].get<std::vector<uint8_t>>();if(bytes.size()<12||std::memcmp(bytes.data(),"GMV1",4))throw std::runtime_error("Missing original layered state");uint32_t count=0;std::memcpy(&count,bytes.data()+4,4);return re::Json::parse((char*)bytes.data()+12+count*4);}
int main(int argc,char**argv){try{if(argc<3)return 2;re::Json cat;std::ifstream(argv[2])>>cat;int engine=-1;for(int i=0;i<int(cat["entries"].size());i++)if(cat["entries"][i]["name"]=="Amino")engine=i;if(engine<0)return 2;auto&defs=cat["sources"][27]["parameters"];int cutoff=-1;for(auto&p:defs)if(p["key"].get<std::string>().find("cutoff")!=std::string::npos){cutoff=p["index"];break;}if(cutoff<0)throw std::runtime_error("Amino cutoff missing");re::Core c("",0,argv[1]);ready(c);c.set(1,engine/float(cat["entries"].size()-1));ready(c);write(c,2,1.f/3);write(c,4,0);write(c,cutoff,.23f);write(c,4,1.f/3);write(c,cutoff,.78f);auto before=native(c);auto saved=c.state();c.set(1,1.f/float(cat["entries"].size()-1));ready(c);c.restore(saved);ready(c);settle(c);auto after=native(c);if(before!=after){std::cerr<<re::Json::diff(before,after).dump()<<std::endl;throw std::runtime_error("Layer state changed");}std::cout<<"LAYER_STATE_PASS Amino two distinct edited layers, source chunk, engine switch, DAW restore\n";}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
